rm:translateY(5px)}to{opacity:1;transform:translateY(0)}}.loading-state{display:flex;align-items:center;justify-content:center;gap:12px;min-height:112px;color:var(--muted);grid-column:1/-1;border:1px solid var(--line);border-radius:12px;background:var(--panel)}.loading-spinner{width:20px;height:20px;border:2px solid #514635;border-top-color:var(--accent2);border-radius:50%;animation:spin .8s linear infinite;flex:none}@keyframes spin{to{transform:rotate(360deg)}}.page-btn{transition:transform .15s ease,border-color .15s ease,background-color .15s ease}.page-btn:not(:disabled):hover{transform:translateY(-1px);background:#272117}.back{transition:transform .15s ease,border-color .15s ease}.back:hover{transform:translateY(-1px)}.channel-head{display:flex;align-items:center;gap:12px;padding:14px;background:#201d18;border-bottom:1px solid var(--line)}.logo{width:48px;height:42px;object-fit:contain;flex:none}.channel-title{min-width:0;flex:1}.channel-title strong{display:block;overflow-wrap:anywhere}.channel-title small{display:block;color:var(--muted);font-size:12px}.programs{padding:6px 14px 12px}.program{display:grid;grid-template-columns:90px minmax(0,1fr);gap:10px;padding:11px 0;border-bottom:1px solid #302d27}.program:last-child{border-bottom:0}.time{color:var(--accent2);font-size:12px;font-weight:800;padding-top:2px}.ptitle{font-weight:750;font-size:14px}.desc{color:var(--muted);font-size:12px;margin-top:3px;overflow-wrap:anywhere}.more-programs{margin:8px 0 3px;padding:8px 10px;font-size:12px}.empty{grid-column:1/-1;color:var(--muted);padding:28px;text-align:center;border:1px dashed #514635;border-radius:10px}.pagination{display:flex;justify-content:center;align-items:center;gap:12px;flex-wrap:wrap;margin:24px 0}.page-status{color:var(--muted);font-size:13px;font-weight:700}.page-btn:disabled{opacity:.4;cursor:not-allowed}.footnote{color:var(--muted);font-size:12px;text-align:center;margin-top:26px}@media(max-width:760px){.tools{grid-template-columns:1fr}.grid{grid-template-columns:1fr}.wrap{padding:16px 12px 34px}.channel-head{padding:12px}.programs{padding:4px 12px 10px}.program{grid-template-columns:76px minmax(0,1fr);gap:8px}.back{padding:9px 10px;font-size:12px}}@media(prefers-reduced-motion:reduce){*,*::before,*::after{animation:none!important;scroll-behavior:auto!important;transition:none!important;transform:none!important}}
