<script type="application/ld+json">{"@context":"https://schema.org","@type":"WebPage","name":"Guia de Programação — Mega Canais TV","inLanguage":"pt-BR","description":"Consulte horários e descrições dos programas por canal no guia de programação do Mega Canais TV."}</script></head><body><a class="skip-link" href="#main-content">Pular para o conteúdo</a><noscript><div style="padding:12px 16px;background:#2a2117;color:#f8f6f1;border-bottom:1px solid #c58b52">O JavaScript está desativado. A interface dinâmica e a programação precisam dele para carregar; ative JavaScript para usar todos os recursos. Os links HTML continuam disponíveis.</div></noscript><main class="wrap" id="main-content"><header><div class="brand">MEGA <span>CANAIS TV</span> · PROGRAMAÇÃO</div><a class="back" href="/">← Voltar aos canais</a></header><h1>Guia completo de programação</h1><p class="intro">Consulte os horários e a descrição dos programas por canal. A lista é paginada para carregar apenas alguns canais por vez e manter a página leve.</p>
<div class="tools"><input id="search" type="search" placeholder="Buscar canal ou programa…" aria-label="Buscar canal ou programa"><select id="date" aria-label="Filtrar por data"><option value="">Todas as datas disponíveis</option></select><select id="sort" aria-label="Ordenar canais"><option value="name">Ordenar por canal</option><option value="time">Ordenar pelo primeiro horário</option></select></div><div class="summary" id="summary" aria-live="polite">Carregando programação…</div><div class="warning" id="warning" hidden></div><section class="grid" id="grid" aria-live="polite"><div class="loading-state" role="status"><span class="loading-spinner" aria-hidden="true"></span><span>Carregando eventos…</span></div></section><nav class="pagination" aria-label="Paginação da programação"><button class="page-btn" id="prev" disabled>‹ Anterior</button><span class="page-status" id="pageStatus">Página 1</span><button class="page-btn" id="next" disabled>Próxima ›</button></nav><p class="footnote">A grade depende das informações disponibilizadas pela fonte EPG. Alguns canais podem não ter horários ou sinopses preenchidos.</p></main>
<script>
const $=s=>document.querySelector(s), norm=v=>String(v==null?'':v).toLowerCase().normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]/g,''), esc=s=>String(s==null?'':s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let channels=[],raw=[],list=[],page=1;const PAGE_SIZE=8,PROGRAMS_INITIAL=8,expanded=new Set();
function dateKey(t){const d=new Date(t);return d.getFullYear()+'-'+String(d.getMonth()+1).padStart(2,'0')+'-'+String(d.getDate()).padStart(2,'0')}
function timeLabel(t){return new Date(t).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})}
function dateLabel(d){return new Date(d+'T12:00:00').toLocaleDateString('pt-BR',{weekday:'short',day:'2-digit',month:'long',year:'numeric'})}
function channelFor(item){const id=norm(item.id);return channels.find(c=>[c.epg_id,c.epg,c.slug,c.id,c.name,c.name&&c.name.replace(/\s*(hd|fhd|sd)$/i,'')].some(v=>norm(v)===id))||null}
function fillDates(){const sel=$('#date'),old=sel.value,dates=[...new Set(raw.flatMap(x=>x.data.map(p=>dateKey(p.t))))].sort();sel.innerHTML='<option value="">Todas as datas disponíveis</option>'+dates.map(d=>`<option value="${d}">${esc(dateLabel(d))}</option>`).join('');if(dates.includes(old))sel.value=old;else{const today=dateKey(Date.now());sel.value=dates.includes(today)?today:''}}
function buildList(){const q=$('#search').value.trim().toLocaleLowerCase('pt-BR'),date=$('#date').value,sort=$('#sort').value;list=raw.map(item=>{const ch=channelFor(item),name=(ch&&ch.name)||item.id,progs=item.data.filter(p=>(!date||dateKey(p.t)===date)&&(!q||name.toLocaleLowerCase('pt-BR').includes(q)||p.title.toLocaleLowerCase('pt-BR').includes(q)||p.desc.toLocaleLowerCase('pt-BR').includes(q)));return {...item,name,ch,progs}}).filter(x=>x.progs.length);list.sort((a,b)=>sort==='time'?(a.progs[0].t-b.progs[0].t):a.name.localeCompare(b.name,'pt-BR'));page=1;render()}
function render(){const totalPages=Math.max(1,Math.ceil(list.length/PAGE_SIZE));page=Math.min(page,totalPages);const start=(page-1)*PAGE_SIZE,subset=list.slice(start,start+PAGE_SIZE),programCount=list.reduce((n,x)=>n+x.progs.length,0);$('#summary').textContent=`${list.length} canais com programação · ${programCount} programas encontrados · exibindo ${subset.length} canais nesta página`;$('#pageStatus').textContent=`Página ${page} de ${totalPages}`;$('#prev').disabled=page<=1;$('#next').disabled=page>=totalPages;const grid=$('#grid');if(!subset.length){grid.innerHTML='<div class="empty">Nenhuma programação encontrada para este filtro.</div>';return}grid.innerHTML=subset.map((item,idx)=>{const logo=item.ch&&(item.ch.logo||item.ch.image||item.ch.logo_url||item.ch.icon)||'';const expandedNow=expanded.has(item.id),shown=expandedNow?item.progs:item.progs.slice(0,PROGRAMS_INITIAL);const progs=shown.map(p=>`<div class="program"><div class="time">${esc(timeLabel(p.t))}</div><div><div class="ptitle">${esc(p.title)}</div>${p.desc?`<div class="desc">${esc(p.desc)}</div>`:''}</div></div>`).join('');return `<article class="channel"><div class="channel-head">${logo?`<img class="logo" loading="lazy" decoding="async" src="${esc(logo)}" alt="" onerror="this.style.display='none'">`:''}<div class="channel-title"><strong>${esc(item.name)}</strong><small>${item.progs.length} programa${item.progs.length===1?'':'s'} nesta seleção</small></div></div><div class="programs">${progs}${item.progs.length>PROGRAMS_INITIAL?`<button class="back more-programs" type="button" data-more="${esc(item.id)}">${expandedNow?'Mostrar menos':`Mostrar todos os ${item.progs.length} programas`}</button>`:''}</div></article>`}).join('');grid.querySelectorAll('[data-more]').forEach(b=>b.addEventListener('click',()=>{const id=b.dataset.more;if(expanded.has(id))expanded.delete(id);else expanded.add(id);render()}))}
$('#prev').addEventListener('click',()=>{if(page>1){page--;render();window.scrollTo(0,0)}});$('#next').addEventListener('click',()=>{if(page<Math.ceil(list.length/PAGE_SIZE)){page++;render();window.scrollTo(0,0)}});$('#search').addEventListener('input',buildList);$('#date').addEventListener('change',buildList);$('#sort').addEventListener('change',buildList);
async function load(){try{const [er,cr]=await Promise.all([fetch('/api/epg.php',{cache:'no-store'}),fetch('/api/api.php',{cache:'no-store'})]);if(!er.ok)throw new Error('Falha ao consultar epg.php');const e=await er.json();if(cr.ok){const c=await cr.json();channels=Array.isArray(c.channels)?c.channels:[]}raw=(Array.isArray(e)?e:[]).filter(x=>x&&Array.isArray(x.data)).map(x=>({id:String(x.id||''),data:x.data.map(p=>({t:Date.parse(p.start_date||''),title:String(p.title||''),desc:String(p.desc||'')})).filter(p=>Number.isFinite(p.t)&&p.title.trim()).sort((a,b)=>a.t-b.t)})).filter(x=>x.data.length);if(!raw.length){$('#summary').textContent='A API não retornou programas com data e título válidos.';$('#warning').hidden=false;$('#warning').textContent='Confira se a fonte EPG está fornecendo programação e se epg.php responde com JSON.';$('#grid').innerHTML='';return}fillDates();buildList()}catch(err){$('#summary').textContent='Não foi possível carregar a programação.';$('#warning').hidden=false;$('#warning').textContent='Confira se /api/epg.php e /api/api.php estão acessíveis e se o servidor consegue consultar a API externa.';$('#grid').innerHTML=''}}load();
</script></body></html>